# Let me create a summary table of the evaluation metrics and their meanings
metrics_info = {
    "faithfulness": {
        "source": "Custom NLI (cross-encoder/nli-deberta-v3-small)",
        "calculation": "Uses Natural Language Inference to check if answer is entailed by retrieved documents. Scores: doc_mean, sentence_mean, min_sentence_score. Uses minimum to penalize mixed true/false answers.",
        "threshold": "0.7 (triggers retry if below)",
        "range": "[0.0, 1.0]",
        "meaning": "Whether generated answer is supported by evidence in retrieved documents"
    },
    "faithfulness_nli": {
        "source": "Same as faithfulness",
        "calculation": "Alias for NLI-based faithfulness score",
        "range": "[0.0, 1.0]",
        "meaning": "Measure of factual accuracy/grounding in retrieved evidence"
    },
    "faithfulness_ragas": {
        "source": "RAGAS library",
        "calculation": "LLM-judge based metric (Qwen2.5-3B-Instruct) that evaluates if answer can be inferred from context",
        "range": "[0.0, 1.0]",
        "meaning": "Alternative faithfulness metric using LLM judgment instead of NLI"
    },
    "answer_relevancy": {
        "source": "RAGAS library",
        "calculation": "Evaluates how relevant the generated answer is to the user question. Uses embedding similarity and LLM judgment.",
        "range": "[0.0, 1.0]",
        "meaning": "Whether answer directly addresses the question asked"
    },
    "context_precision": {
        "source": "RAGAS library",
        "calculation": "Measures % of retrieved chunks that are relevant to answer the question. (# relevant chunks) / (# total retrieved chunks)",
        "range": "[0.0, 1.0]",
        "meaning": "Signal-to-noise ratio: what fraction of retrieved context is actually useful"
    },
    "context_recall": {
        "source": "RAGAS library",
        "calculation": "Measures % of required information from ground truth that was retrieved. (# retrieved chunks with info) / (# chunks needed for ground truth)",
        "range": "[0.0, 1.0]",
        "meaning": "Coverage: did we retrieve enough information to answer the question"
    },
    "bertscore_f1": {
        "source": "BERTScore (microsoft/deberta-xlarge-mnli)",
        "calculation": "F1 score based on contextual embeddings between generated answer and ground truth reference",
        "range": "[0.0, 1.0]",
        "meaning": "Semantic similarity between generated answer and reference answer"
    }
}

for metric, info in metrics_info.items():
    print(f"\n{'='*70}")
    print(f"METRIC: {metric}")
    print(f"{'='*70}")
    for key, value in info.items():
        print(f"{key:20s}: {value}")
EOF
